// All business data is stored in one MongoDB document for this initial migration.
// Writes are serialized so rapid bot actions cannot overwrite a newer snapshot.
let mongoClient = null;
let mongoCollection = null;
let mongoWriteChain = Promise.resolve();
let saved = {};
function saveState() { /* reserved for future persistent conversation-state support */ }

const freshMainData = () => ({
  schemaVersion: 3, nextStockId: 1, nextTicketId: 1001, nextOrderId: 1, nextReminderAccountId: 1,
  reminderAccounts: [], dueClearanceRequests: [], smsActivityEvents: [], stocks: [], orders: [], products: [], customers: {}, resellers: {}, tickets: [], ledger: [], youtubeAdminSelections: {},
  settings: { expiredRepeatReminderEnabled: true, prices: { Prime: 80, YouTube: 120, VPN: 100, "Free Fire": 150 }, freeFirePackages: [{id:"ff-weekly",name:"Weekly Membership",price:155,active:true},{id:"ff-monthly",name:"Monthly Membership",price:760,active:true}], resellerTiers: ["Rate 1", "Rate 2", "Rate 3"] }
});
let data = freshMainData();
function saveData() {
  if (!mongoCollection) {
    console.error("MongoDB is not connected; refusing to save business data locally.");
    return Promise.reject(new Error("MongoDB is not connected"));
  }
  const snapshot = JSON.parse(JSON.stringify(data));
  mongoWriteChain = mongoWriteChain.then(() => mongoCollection.updateOne(
    { _id: "main" },
    { $set: { payload: snapshot, updatedAt: new Date() } },
    { upsert: true }
  )).catch(error => { console.error("MongoDB save failed:", error.message); });
  return mongoWriteChain;
}

function migrateYoutubeRequests() { data.youtubeRequests = youtubeRequests.migrateYoutubeRequests(data.youtubeRequests); }

async function connectMongoAndLoad() {
  const uri = process.env.MONGODB_URI;
  if (!uri) throw new Error("Missing MONGODB_URI. Add your MongoDB Atlas connection string in Replit Secrets.");
  mongoClient = new MongoClient(uri, {
    serverSelectionTimeoutMS: 15000,
    connectTimeoutMS: 15000,
    retryWrites: true
  });
  await mongoClient.connect();
  const db = mongoClient.db(process.env.MONGODB_DB || "eh_gameshop_fresh");
  mongoCollection = db.collection("app_state");
  const stored = await mongoCollection.findOne({ _id: "main" });
  if (stored?.payload && typeof stored.payload === "object" && !Array.isArray(stored.payload)) {
    // Preserve the stocks array reference used by the inventory and reseller modules.
    const stocksRef = data.stocks;
    Object.assign(data, freshMainData(), stored.payload);
    stocksRef.splice(0, stocksRef.length, ...(Array.isArray(data.stocks) ? data.stocks : []));
    data.stocks = stocksRef;
    if (typeof stockPrices !== "undefined") Object.assign(stockPrices, DEFAULT_PRICES, data.settings?.prices || {});
    migratePreviewTemplateDefaults();
    migrateYoutubeRequests();
    data.youtubeAdminSelections = data.youtubeAdminSelections && typeof data.youtubeAdminSelections === "object" ? data.youtubeAdminSelections : {};
    if (data.settings.expiredRepeatReminderEnabled === undefined) data.settings.expiredRepeatReminderEnabled = true;
    if (!Array.isArray(data.settings?.freeFirePackages) || data.settings.freeFirePackages.length===0) data.settings.freeFirePackages=[{id:"ff-weekly",name:"Weekly Membership",price:155,active:true},{id:"ff-monthly",name:"Monthly Membership",price:760,active:true}];
    await saveData(); // Persist legacy YouTube credential/OCR cleanup immediately.
    console.log("MongoDB connected; existing EH Gameshop data loaded.");
  } else {
    await mongoCollection.updateOne(
      { _id: "main" },
      { $set: { payload: data, updatedAt: new Date() } },
      { upsert: true }
    );
    console.log("MongoDB connected; fresh EH Gameshop database initialized.");
  }
}
