registerResellerSystem(bot, { data: data, saveData: saveData, isAdmin, renderPreview: (...args) => renderPreview(...args), sendPreviewMessage: (...args) => sendPreviewMessage(...args), getCatalog: () => resellerProductCatalog(), placeOrder: async ({resellerId,product,quantity,deliveryMode}) => { const r=data.resellers?.[String(resellerId)]; if(!r?.active||!r.creditAuthorized) throw Error('Active reseller credit access is required'); const base=Number(product.price||stockPrices[product.name]||0), unit=tierPrice(r,product.name,base); if(!(unit>0)) throw Error('Product price is not configured'); const order=domain.createResellerCartOrder(data,{resellerId:String(resellerId),lines:[{product:product.name,quantity:Number(quantity),priceEach:unit,packageName:product.package||product.duration||'Standard',durationDays:Number(product.durationDays||30)}]}); order.deliveryMode=deliveryMode==='Manual'?'Manual':'Auto'; if(order.deliveryMode==='Manual'){order.status='Manual Delivery';for(const item of order.items)item.status='Manual Delivery';await saveData();}else{await saveData();} const delivery=order.deliveryMode==='Auto'?await deliverResellerAutoOrder(order):[];for(const adminId of ADMIN_IDS)bot.telegram.sendMessage(Number(adminId),`🤝 <b>RESELLER TELEGRAM ORDER</b>\nOrder: <code>${esc(order.id)}</code>\nReseller: ${esc(r.name||resellerId)} (<code>R-${esc(resellerId)}</code>)\nProduct: ${esc(product.name)}\nQuantity: ${quantity}\nTotal Due: ৳${order.price}\nDelivery: ${order.deliveryMode}\nDelivered: ${delivery.filter(x=>x.delivered).length}/${order.items.length}`,{parse_mode:'HTML'}).catch(()=>{});return {order,due:domain.dueForReseller(data,resellerId),delivery};}, submitYoutubeRequest: async ({resellerId,type,emails,email,product}) => { const r=data.resellers?.[String(resellerId)]; if(!r?.active||!r.creditAuthorized) throw Error('Active reseller credit access is required'); const p=product||resellerProductCatalog().find(x=>String(x.name||'').toLowerCase().includes('youtube')); if(!p) throw Error('YouTube Premium product is not configured'); const unit=tierPrice(r,p.name,Number(p.price||stockPrices[p.name]||0)); if(!(unit>0)) throw Error('YouTube reseller price is not configured'); const items=youtubeRequests.createYoutubeItems({type,emails,email,idPrefix:`YTI-${Date.now()}`}); const total=unit*items.length; const parent={id:`YT-${Date.now()}-${crypto.randomBytes(3).toString('hex')}`,customerId:String(resellerId),resellerId:String(resellerId),customerName:String(r.name||resellerId),product:'YouTube Premium',packageName:'1 Month',unitPrice:unit,price:total,type,status:'Pending Review',items,createdAt:new Date().toISOString(),source:'reseller_telegram',telegramMessages:[]}; (data.youtubeRequests||=[]).push(parent); (data.ledger||=[]).push({id:`LED-${Date.now()}-${parent.id}`,resellerId:String(resellerId),orderId:parent.id,type:'SALE_DUE',debit:total,credit:0,balanceDelta:total,createdAt:parent.createdAt,note:`YouTube ${type==='family'?'Family Invite':'Individual'} · ${items.length} item(s)`}); await saveData(); const adminHtml=`<h2>▶️ RESELLER YOUTUBE ${type.toUpperCase()} REQUEST</h2><table bordered compact><tr><th>REQUEST</th><td><code>${esc(parent.id)}</code></td></tr><tr><th>RESELLER</th><td>${esc(parent.customerName)} · <code>${esc(resellerId)}</code></td></tr><tr><th>TYPE</th><td>${type==='family'?'FAMILY INVITE':'INDIVIDUAL'}</td></tr><tr><th>QUANTITY</th><td>${items.length}</td></tr><tr><th>ITEM STATUS</th><td>${esc(youtubeStatusSummary(parent))}</td></tr><tr><th>UNIT PRICE</th><td>${money(unit)}</td></tr><tr><th>TOTAL DUE</th><td><b>${money(total)}</b></td></tr></table><table bordered compact><tr><th>EMAIL</th><th>STATUS</th><th>ACTION</th></tr>${items.map((it,i)=>`<tr><td>${String(i+1).padStart(2,'0')} · <code>${esc(it.email)}</code></td><td>${esc(it.status)}</td><td><tg-button type="callback_data" style="primary" data="ytadm:item:${esc(parent.id)}:${esc(it.id)}">UPDATE</tg-button></td></tr>`).join('')}</table><tg-button-row><tg-button type="callback_data" style="primary" data="ytadm:req:${esc(parent.id)}">OPEN REQUEST</tg-button></tg-button-row>`;for(const adminId of ADMIN_IDS){try{const sent=await bot.telegram.callApi('sendRichMessage',{chat_id:Number(adminId),rich_message:{html:adminHtml}});domain.trackTelegramMessage(parent,{chatId:sent.chat.id,messageId:sent.message_id,kind:'youtube_admin_request'});}catch(e){console.error('Reseller YouTube request Admin notification failed:',parent.id,e.message);}}await saveData();return parent;} });

