function migratePreviewTemplateDefaults(){
  const saved=data.settings?.previewTemplates;
  if(!saved||typeof saved!=="object"||Array.isArray(saved))return false;
  let changed=false;
  for(const key of Object.keys(LEGACY_PREVIEW_TEMPLATE_DEFAULTS)){
    const current=saved[key],legacy=LEGACY_PREVIEW_TEMPLATE_DEFAULTS[key];
    if(!current||(current.format===legacy.format&&current.html===legacy.html&&current.text===legacy.text&&current.parse_mode===legacy.parse_mode&&JSON.stringify(current.buttons||[])===JSON.stringify(legacy.buttons||[]))){
      saved[key]=JSON.parse(JSON.stringify(DEFAULT_PREVIEW_TEMPLATES[key]));changed=true;
    }
  }
  if(changed)data.settings.previewTemplates=saved;
  return changed;
}
function underlinePlainText(value){return Array.from(String(value||'')).map(ch=>ch===' '?' ':ch+'\u0332').join('');}
function deliveryCopyText(product,packageName,email,password,profile,pin,expiry){
 const heading=underlinePlainText(`${product||'Product'} — ${packageName||'Standard'}`);
 return `${heading}\n\nACCOUNT DETAILS\n📧 Email: ${email||'N/A'}\n🔑 Password: ${password||'N/A'}\n👤 Profile: ${profile||'N/A'}\n🔐 PIN: ${pin||'N/A'}\n📅 Expiry: ${expiry||'N/A'}`;
}
function activePreviewTemplates(){ const saved=data.settings?.previewTemplates||{}; return { ...DEFAULT_PREVIEW_TEMPLATES, ...saved, customer_delivery_new:DEFAULT_PREVIEW_TEMPLATES.customer_delivery_new, reseller_delivery_new:DEFAULT_PREVIEW_TEMPLATES.reseller_delivery_new }; }
function selectedDeliveryTemplate(role='customer'){const selected=data.settings?.mainDeliveryTemplate||'customer_delivery';const suffix=role==='reseller'?'reseller':'customer';if(selected==='customer_delivery_new')return `${suffix}_delivery_new`;if(selected==='customer_delivery_reference')return `${suffix}_delivery_reference`;return `${suffix}_delivery`;}
function orderHistoryTableHtml(order,item){const events=[['🛒','Order Created',order.createdAt],['⏳','Pending',order.createdAt],['🔵','Order Accepted',item?.acceptedAt||order.acceptedAt],['🔄','Processing',item?.processingAt||order.processingAt],['🎉','Order Completed',item?.deliveredAt||order.completedAt]];const lastIndex=item?.status==='Completed'?4:item?.status==='Processing'?3:item?.status==='Accepted'?2:1;return `<table compact>${events.map(([icon,label,at],i)=>`<tr><td align="center"><b>${i===0?'🛒':i<=lastIndex?'●':'○'}</b>${i<events.length-1?'<br/>│':''}</td><td><b>${label}</b><br/>${at?`${fmtDate(at)} · ${dhakaTime(at)}`:'Pending'}</td></tr>`).join('')}</table>`;}
