function escapePreviewValue(value,mode){const v=String(value??"");if(mode==="HTML")return esc(v);if(mode==="MarkdownV2")return v.replace(/([_\*[\]()~`>#+\-=|{}.!\\])/g,"\\$1");if(mode==="Markdown")return v.replace(/([_*`\[])/g,"\\$1");return v;}
function fillPreviewString(template, values, mode, escapeValues=true){return String(template??"").replace(/{{\s*([a-zA-Z0-9_]+)\s*}}/g,(_,key)=>(['timelineHtml','detailsHtml','previewFooter'].includes(key))?String(values[key]??''):escapeValues?escapePreviewValue(values[key],mode):String(values[key]??""));}
function renderPreview(name, values={}){
  const cfg=activePreviewTemplates()[name] || DEFAULT_PREVIEW_TEMPLATES[name];
  if(!cfg) throw new Error(`Preview template '${name}' is missing or invalid`);
  const mode=cfg.format==="rich_markdown"?"Markdown":(cfg.parse_mode||"HTML");
  const keyboardRows=(Array.isArray(cfg.buttons)?cfg.buttons:[]).map(row=>(Array.isArray(row)?row:[]).map(b=>{
    const out={text:fillPreviewString(b.text||"Button",values,null,false)};
    if(b.url)out.url=fillPreviewString(b.url,values,null,false);
    if(b.callback_data)out.callback_data=fillPreviewString(b.callback_data,values,null,false);
    if(b.copy_text)out.copy_text={text:fillPreviewString(b.copy_text,values,null,false)};
    return out;
  }).filter(b=>b.url||b.callback_data||b.copy_text));
  const options={};if(keyboardRows.some(r=>r.length))options.reply_markup={inline_keyboard:keyboardRows.filter(r=>r.length)};
  if(cfg.format==="rich_html"||cfg.format==="rich_markdown"||cfg.rich_message){
    const key=cfg.format==="rich_markdown"?"markdown":"html";
    const source=cfg[key]??cfg.text;
    if(typeof source!=="string")throw new Error(`Rich ${key} template content is required`);
    return {rich:true,rich_message:{[key]:fillPreviewString(source,values,mode,true)},options};
  }
  if(typeof cfg.text!=="string")throw new Error(`Preview template '${name}' requires text`);
  const text=fillPreviewString(cfg.text,values,mode,true);if(cfg.parse_mode)options.parse_mode=cfg.parse_mode;
  return {rich:false,text,options};
}
