function orderTimelineHtml(order,item,deliveryAt=null){const created=timelineTime(order.createdAt);const payment=order.resellerId?`● RESELLER CREDIT ORDER · ◷ ${created}`:order.paymentStatus==='Verified'?`● PAYMENT VERIFIED · ◷ ${timelineTime(order.paymentVerifiedAt)}`:`○ PAYMENT ${String(order.paymentStatus||'PENDING').toUpperCase()} · ◷ ${created}`;const deliveredAt=deliveryAt||item?.deliveredAt;const delivery=(item?.status==='Completed'||deliveryAt)?`● DELIVERY COMPLETED · ◷ ${timelineTime(deliveredAt)}`:`○ DELIVERY PENDING · ◷ ${timelineTime(order.updatedAt||order.createdAt)}`;return `<pre>● ORDER PLACED · ${created}\n│\n${payment}\n│\n${delivery}</pre>`;}
