function money(value) { return `৳${Math.round((Number(value) || 0) * 100) / 100}`; }
function esc(value) {
  return String(value ?? "N/A").replace(/[&<>"']/g, c => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&apos;"
  })[c]);
}

function shorten(value, max = 32) {
  const s = String(value || "N/A");
  return esc(s.length > max ? s.slice(0, Math.max(1, max - 1)) + "…" : s);
}

function dhakaTime(value) {
  const date = new Date(value || Date.now());
  if (Number.isNaN(date.getTime())) return "N/A";
  return new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Dhaka",
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  }).format(date);
}

function getTheme(order) {
  const value = `${order.product || ""} ${order.category || ""}`.toLowerCase();

  if (/free fire|diamond|gaming|game/.test(value)) {
    return { title: "GAMING", color: "#69B8D8", symbol: "◆" };
  }
  if (/youtube|netflix|spotify|ott|streaming/.test(value)) {
    return { title: "STREAMING", color: "#E58A8A", symbol: "▶" };
  }
  if (/vpn/.test(value)) {
    return { title: "PRIVACY & SECURITY", color: "#78BCA2", symbol: "◇" };
  }
  return { title: "DIGITAL PRODUCT", color: "#B4A0D9", symbol: "◆" };
}

async function getCustomerPhoto(userId) {
  try {
    const result = await bot.telegram.getUserProfilePhotos(Number(userId), 0, 1);
    if (!result || !result.total_count || !result.photos?.[0]?.length) return null;

    const photos = result.photos[0];
    const best = photos[photos.length - 1];
    const fileUrl = await bot.telegram.getFileLink(best.file_id);
    const response = await fetch(fileUrl.href);
    if (!response.ok) return null;

    return await sharp(Buffer.from(await response.arrayBuffer()))
      .rotate()
      .resize(120, 120, { fit: "cover", position: "centre" })
      .png()
      .toBuffer();
  } catch (error) {
    console.log("Customer photo unavailable:", error.message);
    return null;
  }
}

function dataUri(buffer, mime = "image/png") {
  return `data:${mime};base64,${buffer.toString("base64")}`;
}

function loadOptionalImage(fileName) {
  const filePath = path.join(ASSET_DIR, fileName);
  if (!fs.existsSync(filePath)) return null;
  try {
    return fs.readFileSync(filePath);
  } catch {
    return null;
  }
}

