const stockFlows = new Map();
// Cancel an old stock text prompt when a user chooses another action or menu.
bot.use(async (ctx, next) => {
  const id = ctx.from?.id;
  if (id && ctx.callbackQuery?.data) {
    const action = String(ctx.callbackQuery.data);
    if (!/^stockprice:(?:default|custom)$/.test(action) && !/^link_customer_/.test(action)) stockFlows.delete(id);
  }
  if (id && ctx.message?.text) {
    const input = String(ctx.message.text).trim();
    const activeFlow = stockFlows.get(id);
    if (activeFlow?.mode === "linkCustomer" && !input.startsWith('/')) return next();
    const menuLabels = new Set([
      '🌐 Open EH Gameshop','📦 Stock Center','👤 Account & Profiles','📋 Orders / Reports',
      '🤝 Reseller Management','💳 Due Requests','🛠 Support Inbox','🤝 Reseller Panel',
      '📦 My Orders','🔎 Order Search','🆘 Support','Back','⬅️ Back','Cancel','❌ Cancel','Main Menu'
    ]);
    if (input.startsWith('/') || menuLabels.has(input)) stockFlows.delete(id);
  }
  return next();
});
const STOCK_PRODUCTS = ["Prime", "YouTube", "VPN", "Free Fire", "Crunchyroll"];
