function parseDateInput(value) {
  const v = String(value || "").trim();
  let m = v.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);
  if (m) { const y=+m[1],mo=+m[2],day=+m[3],d=new Date(Date.UTC(y,mo-1,day)); return d.getUTCFullYear()===y&&d.getUTCMonth()===mo-1&&d.getUTCDate()===day?`${y}-${String(mo).padStart(2,'0')}-${String(day).padStart(2,'0')}`:null; }
  m = v.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4}|\d{2})$/);
  if (m) { let y=+m[3];if(y<100)y+=2000;const mo=+m[2],day=+m[1],d=new Date(Date.UTC(y,mo-1,day));return d.getUTCFullYear()===y&&d.getUTCMonth()===mo-1&&d.getUTCDate()===day?`${y}-${String(mo).padStart(2,'0')}-${String(day).padStart(2,'0')}`:null; }
  // Short user format: day + month only. Select the current year's date if today
  // or future; otherwise select the next occurrence in the following year.
  m = v.match(/^(\d{1,2})\s*[-/. ]\s*(\d{1,2})$/);
  if (m) {
    const day=+m[1],mo=+m[2];if(mo<1||mo>12||day<1||day>31)return null;
    const today=dhakaToday();let year=Number(today.slice(0,4));
    const make=(y)=>{const d=new Date(Date.UTC(y,mo-1,day));return d.getUTCFullYear()===y&&d.getUTCMonth()===mo-1&&d.getUTCDate()===day?`${y}-${String(mo).padStart(2,'0')}-${String(day).padStart(2,'0')}`:null;};
    let result=make(year);if(!result)return null;if(result<today)result=make(year+1);return result;
  }
  return null;
}
function dhakaToday() { return new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Dhaka", year:"numeric", month:"2-digit", day:"2-digit" }).format(new Date()); }
function refreshStockLifecycle(stock,today=dhakaToday()){
  if(!stock||stock.lifecycleStatus==="Archived")return stock;
  const accountExpired=String(stock.originalExpiry||"")<today;
  const running=(stock.profiles||[]).filter(p=>p.active!==false&&p.status!=="Replaced"&&(p.customerId||p.customerLinked)&&p.customerExpiry&&String(p.customerExpiry)>=today);
  if(accountExpired){stock.status="Expired";stock.lifecycleStatus=running.length?"Expired":"Archived";if(!running.length)stock.archivedAt=stock.archivedAt||new Date().toISOString();}
  else if(stock.lifecycleStatus!=="Archived"){stock.lifecycleStatus="Active";if(!stock.profiles?.length)stock.status="Available";}
  stock.updatedAt=new Date().toISOString();return stock;
}
function refreshAllStockLifecycle(){let changed=false;for(const st of stocks){const before=`${st.lifecycleStatus||""}|${st.status||""}`;refreshStockLifecycle(st);const after=`${st.lifecycleStatus||""}|${st.status||""}`;if(before!==after)changed=true;}if(changed&&mongoCollection)saveData();return changed;}

function dateOnly(value) { const parsed = parseDateInput(value); return parsed ? new Date(`${parsed}T12:00:00+06:00`) : null; }
function addDays(date, days) { const d = new Date(date); d.setDate(d.getDate()+days); return d; }
function isoPlusDays(iso, days) { const d = new Date(`${iso}T12:00:00+06:00`); d.setDate(d.getDate()+days); return new Intl.DateTimeFormat("en-CA", {timeZone:"Asia/Dhaka",year:"numeric",month:"2-digit",day:"2-digit"}).format(d); }
function fmtDate(value) { const d = typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value) ? new Date(`${value}T12:00:00+06:00`) : new Date(value); if(Number.isNaN(d.getTime())) return "—"; return new Intl.DateTimeFormat("en-GB", { timeZone:"Asia/Dhaka", day:"2-digit", month:"short", year:"numeric" }).format(d); }
