async function sendExpiryReminder(stock, daysLeft) {
  const activeProfiles=(stock.profiles||[]).filter(p=>p.active!==false&&p.status!=="Deleted");
  const profileRows=activeProfiles.map((p,i)=>`<tr><td>${String(i+1).padStart(2,"0")} · ${esc(p.profile||`Profile ${i+1}`)}</td><td>${esc(p.customerName||p.customerId||"Available")}</td><td>${p.customerExpiry?esc(fmtDateShort(p.customerExpiry)):"—"}</td><td>${domain.extraDays(p.customerExpiry,stock.originalExpiry)>0?`+${domain.extraDays(p.customerExpiry,stock.originalExpiry)} Days`:"—"}</td></tr>`).join("")||'<tr><td colspan="4">No profiles linked.</td></tr>';
  const kind=daysLeft===7?"7 DAYS LEFT":daysLeft===3?"3 DAYS LEFT":daysLeft===1?"1 DAY LEFT":daysLeft===0?"EXPIRES TODAY":`${daysLeft} DAYS LEFT`;
  const alertTitle=daysLeft<0?"🚨 জরুরি সতর্কতা — অ্যাকাউন্টের মেয়াদ শেষ!":daysLeft===0?"🚨 আজই অ্যাকাউন্টের মেয়াদ শেষ হচ্ছে!":daysLeft===1?"⚠️ উচ্চ সতর্কতা — আর মাত্র ১ দিন বাকি!":`⚠️ সতর্কতা — আর ${daysLeft} দিন বাকি!`;const html=`<h2>🚨 ${esc(alertTitle)}</h2><p><b>দয়া করে দ্রুত ব্যবস্থা নিন। এই অ্যাকাউন্টের মেয়াদ শেষ হলে সংশ্লিষ্ট Profile/Service বন্ধ হয়ে যেতে পারে।</b></p><p><tg-button type="disabled" style="${daysLeft<=1?'danger':'primary'}">${kind}</tg-button></p><table bordered compact><tr><th>PRODUCT</th><td><b>${esc(stock.product)}</b></td></tr><tr><th>STOCK ID</th><td><code>${esc(stock.id)}</code></td></tr><tr><th>EMAIL / ID</th><td><code>${esc(stock.email)}</code></td></tr><tr><th>PASSWORD</th><td><code>${esc(stock.password)}</code></td></tr><tr><th>ORIGINAL EXPIRY</th><td><b>${esc(fmtDateShort(stock.originalExpiry))}</b></td></tr></table><h3>PROFILE DETAILS</h3><table bordered compact><tr><th>PROFILE</th><th>CUSTOMER</th><th>CUSTOMER EXPIRY</th><th>EXTRA DAYS</th></tr>${profileRows}</table><p><i>Admin reminder · EH Gameshop · Asia/Dhaka</i></p>`;
  const outcomes=await Promise.all([...ADMIN_IDS].map(async adminId=>{try{await bot.telegram.callApi("sendRichMessage",{chat_id:Number(adminId),rich_message:{html}});return true;}catch(e){console.error("Expiry reminder delivery failed for Admin",adminId,e.message);return false;}}));
  if(!outcomes.some(Boolean))throw Error('Reminder could not be delivered to any configured Admin');
}
// Overlap guard: a slow Telegram send must never let the next scheduled run send the same reminder twice.
let expiryChecksRunning = false;
async function runExpiryChecks() { if (expiryChecksRunning) return; expiryChecksRunning = true; try { await runExpiryChecksOnce(); } finally { expiryChecksRunning = false; } }
async function runExpiryChecksOnce() {
  refreshAllStockLifecycle();
  const today = dhakaToday();
  let reminderStateChanged = false;
  for (const stock of stocks) {
    if (!ADMIN_IDS.size) continue;
    if (stock.lifecycleStatus === 'Archived' || stock.status === 'Archived') continue;
    const due = domain.expiryReminderDue(stock, today);
    if (due) {
      try { await sendExpiryReminder(stock, due.daysLeft); domain.markExpiryReminderSent(stock, due.key); reminderStateChanged = true; }
      catch (e) { console.error("Admin stock expiry reminder failed:", stock.id, e.message); }
    }
    if (data.settings?.expiredRepeatReminderEnabled !== false && stock.originalExpiry && String(stock.originalExpiry).slice(0,10) < today) {
      const last = Number(stock.expiredRepeatReminderSentAt || 0);
      if (!last || Date.now() - last >= 30 * 60 * 1000) {
        try {
          const html = `<h2>🚨 ACCOUNT EXPIRED · RENEWAL REQUIRED</h2><p><tg-button type="disabled" style="danger">EXPIRED</tg-button></p><table bordered compact><tr><th>PRODUCT</th><td><b>${esc(stock.product)}</b></td></tr><tr><th>STOCK ID</th><td><code>${esc(stock.id)}</code></td></tr><tr><th>ACCOUNT</th><td><code>${esc(stock.email || '—')}</code></td></tr><tr><th>EXPIRY DATE</th><td><b>${fmtDate(stock.originalExpiry)}</b></td></tr></table><p>This account has expired. Please renew or update its expiry date.</p><tg-button-row><tg-button type="callback_data" style="primary" data="reminder_stock:${esc(stock.id)}">VIEW ACCOUNT</tg-button><tg-button type="callback_data" style="danger" data="reminder_toggle_repeat">STOP ALERTS</tg-button></tg-button-row>`;
          const results = await Promise.all([...ADMIN_IDS].map(async adminId => { try { await bot.telegram.callApi('sendRichMessage',{chat_id:Number(adminId),rich_message:{html}}); return true; } catch(e) { console.error('Repeated expired-account alert failed:',stock.id,e.message); return false; } }));
          if (results.some(Boolean)) { stock.expiredRepeatReminderSentAt = Date.now(); reminderStateChanged = true; }
        } catch(e) { console.error('Repeated expired-account alert failed:',stock.id,e.message); }
      }
    }
  }
  if (reminderStateChanged) await saveData();
}

