// -------------------- MINI APP STOCK SEARCH API (ADMIN AUTHENTICATED) --------------------
function verifyWebAppInitData(initData) {
  if (!TOKEN || !initData) return null;
  const params=new URLSearchParams(initData); const hash=params.get("hash"); if(!hash) return null; params.delete("hash");
  const authDate=Number(params.get("auth_date")||0); if(!authDate || Math.abs(Date.now()/1000-authDate)>86400) return null;
  const dataCheck=[...params.entries()].sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>`${k}=${v}`).join("\n");
  const secret=crypto.createHmac("sha256","WebAppData").update(TOKEN).digest();
  const calculated=crypto.createHmac("sha256",secret).update(dataCheck).digest("hex");
  const a=Buffer.from(calculated,"hex"), b=Buffer.from(hash,"hex"); if(a.length!==b.length||!crypto.timingSafeEqual(a,b)) return null;
  try { const user=JSON.parse(params.get("user")||"{}"); return user && user.id ? user : null; } catch { return null; }
}
const app=express(); app.use(express.json({limit:"5mb"})); app.use(express.static(path.join(__dirname,"Public"))); app.use("/assets",express.static(path.join(__dirname,"assets")));
function webhookTokenMatches(req){
 const expected=String(process.env.SMS_WEBHOOK_SECRET||'');if(!expected)return false;
 const supplied=String(req.get('authorization')||'').replace(/^Bearer\s+/i,'').trim();
 const a=Buffer.from(supplied),b=Buffer.from(expected);return a.length===b.length&&crypto.timingSafeEqual(a,b);
}
function smsManualReviewHtml(event){return `<h2>📩 SMS ACTIVITY · MANUAL REVIEW</h2><table bordered compact><tr><th>EVENT</th><td><code>${esc(event.id)}</code></td></tr><tr><th>SOURCE</th><td>${esc(event.from||'Unknown')}</td></tr><tr><th>TRANSACTION ID</th><td><code>${esc(event.transactionId||'Not detected')}</code></td></tr><tr><th>AMOUNT</th><td>${event.amountMinor===null?'Not detected':`৳${(event.amountMinor/100).toFixed(2)}`}</td></tr><tr><th>REASON</th><td>${esc(event.reason||'Needs Admin review')}</td></tr><tr><th>SMS TEXT</th><td>${esc(event.text||'').slice(0,1400)}</td></tr><tr><th>STATUS</th><td><b>${esc(event.status)}</b></td></tr></table>`;}
async function notifySmsManualReview(event){
 event.telegramMessages||=[];
 for(const adminId of ADMIN_IDS)try{const sent=await bot.telegram.callApi('sendRichMessage',{chat_id:Number(adminId),rich_message:{html:smsManualReviewHtml(event)}});domain.trackTelegramMessage(event,{chatId:sent.chat.id,messageId:sent.message_id,kind:'sms_manual_review'});}catch(e){console.error('SMS Activity Admin Review notification failed:',e.message);}
 await saveData();
}
async function syncSmsManualReview(event){return syncTrackedMessages({targets:[event],telegram:bot.telegram,save:saveData,render:async()=>({rich:true,rich_message:{html:smsManualReviewHtml(event)}}),sendFallback:async(ref,rendered)=>bot.telegram.callApi('sendRichMessage',{chat_id:Number(ref.chatId),rich_message:rendered.rich_message})});}
function verifyOrderFromSms(order,event){
 if(order.paymentStatus!=='Pending Verification'||String(order.paymentMethod||'').toLowerCase()!=='bkash'||String(order.transactionId||'').toUpperCase()!==String(event.transactionId||'').toUpperCase()||Math.round(Number(order.price||0)*100)!==Number(event.amountMinor))throw Error('Order no longer matches this SMS payment');
 order.paymentStatus='Verified';order.paymentVerifiedAt=new Date().toISOString();order.paymentVerifiedBy='SMS Activity';order.paymentVerificationSource='SMS Activity';order.paymentVerificationEventId=event.id;
 if(order.orderType==='Subscription')order.status='Awaiting Stock';else if(['Pending Payment Verification','Pending Purchase','Rejected'].includes(order.status))order.status='Accepted';
 recordOrderEvent(order,'PAYMENT_AUTO_VERIFIED','SMS Activity',{transactionId:event.transactionId,eventId:event.id});
}
async function verifyDueFromSms(request,event){
 if(request.status!=='Pending'||String(request.paymentMethod||'').toLowerCase()!=='bkash'||String(request.transactionId||'').toUpperCase()!==String(event.transactionId||'').toUpperCase()||Math.round(Number(request.amount||0)*100)!==Number(event.amountMinor))throw Error('Due request no longer matches this SMS payment');
 const row=domain.settleResellerDue(data,request.resellerId,request.amount,{transactionId:event.transactionId,paymentMethod:'bKash',confirmedBy:'SMS Activity',requestId:request.id});
 request.status='Confirmed';request.confirmedAt=new Date().toISOString();request.confirmedBy='SMS Activity';request.ledgerId=row.id;request.autoVerifiedAt=new Date().toISOString();
 return row;
}
app.post('/webhook/sms-activity',async(req,res)=>{
 if(!process.env.SMS_WEBHOOK_SECRET)return res.status(503).json({ok:false,error:'SMS webhook secret is not configured'});
 if(!webhookTokenMatches(req))return res.status(401).json({ok:false,error:'Unauthorized'});
 const payload=req.body||{};if(typeof payload.text!=='string'||typeof payload.from!=='string')return res.status(400).json({ok:false,error:'Expected JSON fields: from and text'});
 const result=smsActivity.classifySms(data,payload,{sender:process.env.BKASH_SMS_SENDER||''});
 if(result.action==='duplicate_payload')return res.status(200).json({ok:true,action:'duplicate_payload'});
 if(result.action==='ignored_source')return res.status(202).json({ok:true,action:'ignored_source'});
 const parsed=result.parsed;const event={id:`SMS-${Date.now()}-${crypto.randomBytes(3).toString('hex')}`,fingerprint:result.fingerprint,from:parsed.source,text:String(parsed.text||'').slice(0,2000),sentStamp:parsed.sentStamp,receivedStamp:parsed.receivedStamp,sim:parsed.sim,transactionId:parsed.transactionId,amountMinor:parsed.amountMinor,payerPhone:parsed.payerPhone,status:'Manual Review',reason:result.reason||null,receivedAt:new Date().toISOString(),targetType:result.targetType||null,targetId:result.targetId||null,telegramMessages:[]};
 data.smsActivityEvents||=[];data.smsActivityEvents.push(event);if(data.smsActivityEvents.length>500)data.smsActivityEvents.splice(0,data.smsActivityEvents.length-500);
 if(result.action==='duplicate_transaction'){event.status='Duplicate';event.reason=result.reason||'Transaction ID already processed';await saveData();return res.status(200).json({ok:true,action:'duplicate_transaction',eventId:event.id});}
 if(result.action==='auto_verify'){
  try{
   if(result.targetType==='customer_order'){const order=(data.orders||[]).find(x=>x.id===result.targetId);if(!order)throw Error('Matched customer order no longer exists');verifyOrderFromSms(order,event);event.status='Auto Verified';event.linkedType='customer_order';event.linkedId=order.id;await saveData();await ensureOrderStatusMessage(order,order.customerId||order.resellerId);await notifyAdminPaymentReview(order);await syncOrderTelegramMessages(order);}
   else if(result.targetType==='reseller_due'){const request=(data.dueClearanceRequests||[]).find(x=>x.id===result.targetId);if(!request)throw Error('Matched reseller due request no longer exists');verifyDueFromSms(request,event);event.status='Auto Verified';event.linkedType='reseller_due';event.linkedId=request.id;await saveData();if(!(request.telegramMessages||[]).length)await sendDueClearanceMessages(request);await syncDueClearanceMessages(request);}
   else throw Error('Unsupported payment target');
   await saveData();return res.status(200).json({ok:true,action:'auto_verified',eventId:event.id,linkedType:event.linkedType,linkedId:event.linkedId});
  }catch(e){event.status='Manual Review';event.reason=e.message;await saveData();await notifySmsManualReview(event);return res.status(202).json({ok:true,action:'manual_review',eventId:event.id,reason:event.reason});}
 }
 await saveData();await notifySmsManualReview(event);return res.status(202).json({ok:true,action:'manual_review',eventId:event.id,reason:event.reason});
});
