app.post('/api/admin/sms-activity/events/:id/resolve',async(req,res)=>{if(!adminAuth(req,res))return;const event=(data.smsActivityEvents||[]).find(x=>x.id===req.params.id);if(!event)return res.status(404).json({ok:false,error:'SMS Activity event not found'});if(event.status!=='Manual Review')return res.status(409).json({ok:false,error:`Event is already ${event.status}`});try{const targetType=String(req.body?.targetType||''),targetId=String(req.body?.targetId||'');if(!event.transactionId||event.amountMinor===null)throw Error('This SMS does not contain a reliably parsed Transaction ID and amount');if(targetType==='customer_order'){const order=(data.orders||[]).find(x=>x.id===targetId);if(!order)throw Error('Customer order not found');verifyOrderFromSms(order,event);event.linkedType=targetType;event.linkedId=order.id;}
 else if(targetType==='reseller_due'){const request=(data.dueClearanceRequests||[]).find(x=>x.id===targetId);if(!request)throw Error('Reseller due request not found');verifyDueFromSms(request,event);event.linkedType=targetType;event.linkedId=request.id;}
 else throw Error('targetType must be customer_order or reseller_due');event.status='Manually Verified';event.reviewedBy=String(webUser(req).id);event.reviewedAt=new Date().toISOString();event.adminNote=String(req.body?.note||'Manually verified by Admin').slice(0,500);await saveData();if(event.linkedType==='customer_order'){const order=(data.orders||[]).find(x=>x.id===event.linkedId);await ensureOrderStatusMessage(order,order.customerId||order.resellerId);await notifyAdminPaymentReview(order);await syncOrderTelegramMessages(order);}else{const request=(data.dueClearanceRequests||[]).find(x=>x.id===event.linkedId);if(!(request.telegramMessages||[]).length)await sendDueClearanceMessages(request);await syncDueClearanceMessages(request);}await syncSmsManualReview(event);return res.json({ok:true,event});}catch(e){return res.status(409).json({ok:false,error:e.message});}});


