function portalCatalog(){
  const configured=(data.products||[]).filter(p=>p.active!==false);
  if(configured.length)return configured.map(p=>({id:String(p.id||p.name),name:p.name,category:p.category||"Other",package:p.package||p.duration||"Standard",durationDays:Number(p.durationDays||0),price:Number(p.price||0),description:p.description||"",logo:p.logo||"",active:true}));
  const defaults=[
    ["YouTube Premium","Entertainment","1 Month",30,"YouTube","/assets/youtube-premium.png","Premium ad-free video experience"],
    ["Netflix","Entertainment","1 Month",30,"Netflix","/assets/netflix.svg","Movies and series subscription"],
    ["Amazon Prime","Entertainment","1 Month",30,"Prime","/assets/prime-video.png","Prime Video membership"],
    ["Crunchyroll","Entertainment","1 Month",30,"Crunchyroll","/assets/crunchyroll.png","Anime streaming membership"],
    ["VPN Subscription","Privacy & VPN","30 Days",30,"VPN","/assets/vpn.svg","Secure browsing subscription"],
    ["Canva Pro","Productivity","1 Month",30,"Canva","/assets/canva.svg","Premium design tools"],
    ["Duolingo","Education","1 Month",30,"Duolingo","/assets/duolingo.svg","Language learning subscription"],
    ["Spotify","Music","1 Month",30,"Spotify","/assets/spotify.svg","Music streaming subscription"],
    ["Free Fire Top-up","Gaming","Top-up",0,"Free Fire","/assets/freefire.svg","Fast and reliable game top-up"]
  ];
  return defaults.map(([name,category,pkg,durationDays,key,logo,description])=>({id:key.toLowerCase().replace(/[^a-z0-9]+/g,"-"),name,category,package:pkg,durationDays,price:Number(stockPrices[name]||stockPrices[key]||0),logo,description,active:true}));
}
