app.put('/api/admin/portal-settings',async(req,res)=>{if(!adminAuth(req,res))return;try{const b=req.body||{},current=portalSettings();const next={...current};for(const k of ['brandName','tagline'])if(b[k]!==undefined){const v=String(b[k]).trim();if(!v||v.length>(k==='brandName'?48:100))throw Error(`${k} is required and too long`);next[k]=v;}if(b.accent!==undefined){if(!/^#[0-9a-fA-F]{6}$/.test(String(b.accent)))throw Error('Accent must be a six-digit HEX colour');next.accent=String(b.accent);}if(b.font!==undefined){if(!['Inter','Manrope','DM Sans','Roboto','Nunito Sans'].includes(b.font))throw Error('Unsupported font');next.font=b.font;}if(b.buttonStyle!==undefined){if(!['rounded','pill','square'].includes(b.buttonStyle))throw Error('Invalid button style');next.buttonStyle=b.buttonStyle;}if(b.layout!==undefined){if(!['comfortable','compact'].includes(b.layout))throw Error('Invalid layout density');next.layout=b.layout;}if(b.logo!==undefined){const logo=String(b.logo);if(logo.length>650000||!(logo===''||/^\/(?:eh-logo\.png|assets\/[a-z0-9._-]+\.(?:png|svg))$/i.test(logo)||/^data:image\/(?:png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(logo)))throw Error('Logo must be a bundled image or PNG/JPG/WEBP image under 450KB');next.logo=logo;}data.settings.portal=next;await saveData();res.json({ok:true,settings:next});}catch(e){res.status(400).json({ok:false,error:e.message});}});
