app.post('/api/admin/products',async(req,res)=>{if(!adminAuth(req,res))return;try{const b=req.body||{},name=String(b.name||'').trim(),price=Number(b.price),logo=String(b.logo||'');if(logo&&!/^\/(?:eh-logo\.png|assets\/[a-z0-9._-]+\.(?:png|svg))$/i.test(logo))throw Error('Choose a bundled product logo');if(!name||name.length>80)throw Error('Product name is required (max 80 characters)');if(!Number.isFinite(price)||price<0)throw Error('Enter a valid product price');if((data.products||[]).some(p=>String(p.name||'').toLowerCase()===name.toLowerCase()))throw Error('A product with this name already exists');const item={id:crypto.randomUUID(),name,category:String(b.category||'Other').slice(0,48),package:String(b.package||'Standard').slice(0,48),durationDays:Math.max(0,Math.min(3650,Number(b.durationDays)||0)),price,description:String(b.description||'').slice(0,240),logo,active:b.active!==false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};data.products||=[];data.products.push(item);await saveData();res.status(201).json({ok:true,item});}catch(e){res.status(400).json({ok:false,error:e.message});}});
app.patch('/api/admin/products/:id',async(req,res)=>{if(!adminAuth(req,res))return;const p=(data.products||[]).find(x=>String(x.id)===req.params.id);if(!p)return res.status(404).json({ok:false,error:'Product not found'});try{const b=req.body||{};if(b.name!==undefined){const name=String(b.name).trim();if(!name||name.length>80)throw Error('Invalid product name');if((data.products||[]).some(x=>x!==p&&String(x.name||'').toLowerCase()===name.toLowerCase()))throw Error('Product name already exists');p.name=name;}for(const k of ['category','package','description','logo'])if(b[k]!==undefined){const value=String(b[k]);if(k==='logo'&&value&&!/^\/(?:eh-logo\.png|assets\/[a-z0-9._-]+\.(?:png|svg))$/i.test(value))throw Error('Choose a bundled product logo');p[k]=value.slice(0,k==='description'?240:100);}if(b.price!==undefined){const price=Number(b.price);if(!Number.isFinite(price)||price<0)throw Error('Invalid price');p.price=price;}if(b.durationDays!==undefined)p.durationDays=Math.max(0,Math.min(3650,Number(b.durationDays)||0));if(b.active!==undefined)p.active=Boolean(b.active);p.updatedAt=new Date().toISOString();await saveData();res.json({ok:true,item:p});}catch(e){res.status(400).json({ok:false,error:e.message});}});
app.delete('/api/admin/products/:id',async(req,res)=>{if(!adminAuth(req,res))return;const p=(data.products||[]).find(x=>String(x.id)===req.params.id);if(!p)return res.status(404).json({ok:false,error:'Product not found'});p.active=false;p.archivedAt=new Date().toISOString();await saveData();res.json({ok:true,archived:true,item:p});});


