app.post('/api/admin/due-clearance-requests/:id/confirm',async(req,res)=>{if(!adminAuth(req,res))return;const r=(data.dueClearanceRequests||[]).find(x=>x.id===req.params.id);if(!r)return res.status(404).json({ok:false,error:'Payment request not found'});if(r.status!=='Pending')return res.status(409).json({ok:false,error:`Request is already ${r.status}`});try{const row=domain.settleResellerDue(data,r.resellerId,r.amount,{transactionId:r.transactionId,paymentMethod:r.paymentMethod,confirmedBy:String(webUser(req).id),requestId:r.id});r.status='Confirmed';r.confirmedAt=new Date().toISOString();r.confirmedBy=String(webUser(req).id);r.ledgerId=row.id;await saveData();await syncDueClearanceMessages(r);return res.json({ok:true,request:r,settlement:row,due:domain.dueForReseller(data,r.resellerId)});}catch(e){return res.status(400).json({ok:false,error:e.message});}});
app.post('/api/admin/due-clearance-requests/:id/reject',async(req,res)=>{if(!adminAuth(req,res))return;const r=(data.dueClearanceRequests||[]).find(x=>x.id===req.params.id);if(!r)return res.status(404).json({ok:false,error:'Payment request not found'});if(r.status!=='Pending')return res.status(409).json({ok:false,error:`Request is already ${r.status}`});r.status='Rejected';r.rejectedAt=new Date().toISOString();r.rejectedBy=String(webUser(req).id);r.adminNote=String(req.body?.note||'Payment could not be verified').slice(0,500);await saveData();await syncDueClearanceMessages(r);return res.json({ok:true,request:r,due:domain.dueForReseller(data,r.resellerId)});});
app.get('/api/reseller/due-clearance-requests',(req,res)=>{const u=webUser(req);if(!u)return res.status(401).json({ok:false,error:'Telegram authentication required'});const id=String(u.id),r=data.resellers?.[id];if(!r?.active)return res.status(403).json({ok:false,error:'Active reseller access required'});res.json({ok:true,due:domain.dueForReseller(data,id),items:(data.dueClearanceRequests||[]).filter(x=>x.resellerId===id).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))});});
app.post('/api/reseller/due-clearance-requests',async(req,res)=>{const u=webUser(req);if(!u)return res.status(401).json({ok:false,error:'Telegram authentication required'});const id=String(u.id),r=data.resellers?.[id];if(!r?.active)return res.status(403).json({ok:false,error:'Active reseller access required'});try{const amount=Number(req.body?.amount),due=domain.dueForReseller(data,id),method=String(req.body?.paymentMethod||'').trim(),trx=String(req.body?.transactionId||'').trim();if(!Number.isFinite(amount)||amount<=0||amount>due)throw Error(`Enter an amount up to your current due ৳${due.toFixed(2)}`);if(!method||!trx)throw Error('Payment method and Transaction ID are required');if(trx.length<4||trx.length>100)throw Error('Invalid Transaction ID');if((data.dueClearanceRequests||[]).some(x=>String(x.transactionId||'').toLowerCase()===trx.toLowerCase())||(data.ledger||[]).some(x=>String(x.transactionId||'').toLowerCase()===trx.toLowerCase()))throw Error('This Transaction ID has already been submitted');const reqId=`DCR-${String(Date.now())}`;const item={id:reqId,resellerId:id,resellerName:r.name||id,amount,paymentMethod:method,transactionId:trx,status:'Pending',createdAt:new Date().toISOString(),telegramMessages:[]};(data.dueClearanceRequests||=[]).push(item);await saveData();await sendDueClearanceMessages(item);return res.status(201).json({ok:true,request:item,due,paymentStatus:'Pending Admin Verification'});}catch(e){return res.status(400).json({ok:false,error:e.message});}});
// ---------------- CUSTOMER & SUBSCRIPTION MANAGEMENT ----------------
function customerRecord(id){data.customers||={};return data.customers[String(id)]||null;}
function validIsoDate(v){const x=String(v||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(x))return false;const d=new Date(x+'T12:00:00+06:00');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===x;}
function customerSubscriptions(id){const out=[];for(const st of stocks)for(const p of st.profiles||[])if(String(p.customerId||'')===String(id)&&p.status!=='Replaced'&&p.active!==false)out.push({stockId:st.id,product:st.product,profileId:p.id,profile:p.profile,customerExpiry:p.customerExpiry||null,originalAccountExpiry:st.originalExpiry||null,status:p.status||'Linked',resellerId:p.resellerId||null,history:p.history||[],subscriptionHistory:p.subscriptionHistory||[],extraDaysRequired:Number(p.extraDaysRequired||0)});return out;}
app.get('/api/admin/customers',(req,res)=>{if(!adminAuth(req,res))return;const q=String(req.query.q||'').trim().toLowerCase(),ids=new Set([...Object.keys(data.customers||{}),...(data.orders||[]).map(o=>String(o.customerId||'')),...stocks.flatMap(s=>(s.profiles||[]).map(p=>String(p.customerId||'')))].filter(Boolean));const items=[...ids].map(id=>{const c=data.customers?.[id]||{},orders=(data.orders||[]).filter(o=>String(o.customerId||'')===id||(o.items||[]).some(i=>String(i.customerId||'')===id));return {id,name:c.name||orders[0]?.customerName||id,phone:c.phone||'',email:c.email||'',notes:c.notes||'',active:c.active!==false,createdAt:c.createdAt||null,orders:orders.length,orderHistory:orders.map(o=>({id:o.id,product:o.product||o.packageName,status:o.status,paymentStatus:o.paymentStatus,price:o.price,createdAt:o.createdAt,items:(o.items||[]).map(i=>({id:i.id,product:i.product,status:i.status,customerExpiry:i.customerExpiry}))})),subscriptions:customerSubscriptions(id)};}).filter(c=>!q||[c.id,c.name,c.phone,c.email,c.notes,...c.subscriptions.flatMap(x=>[x.product,x.profile,x.stockId])].some(v=>String(v||'').toLowerCase().includes(q))).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));res.json({ok:true,items});});
app.post('/api/admin/customers',(req,res)=>{if(!adminAuth(req,res))return;try{const id=String(req.body?.telegramId||req.body?.id||'').trim(),name=String(req.body?.name||'').trim();if(!/^[0-9]{5,20}$/.test(id)||!name)throw Error('Valid Telegram ID and customer name are required');data.customers||={};if(data.customers[id])throw Error('Customer already exists');data.customers[id]={id,name,phone:String(req.body?.phone||'').trim(),email:String(req.body?.email||'').trim(),notes:String(req.body?.notes||'').trim(),active:true,createdAt:new Date().toISOString(),subscriptionHistory:[]};saveData();res.status(201).json({ok:true,item:data.customers[id]});}catch(e){res.status(400).json({ok:false,error:e.message});}});
app.patch('/api/admin/customers/:id',(req,res)=>{if(!adminAuth(req,res))return;const c=customerRecord(req.params.id);if(!c)return res.status(404).json({ok:false,error:'Customer not found'});for(const k of ['name','phone','email','notes'])if(req.body?.[k]!==undefined)c[k]=String(req.body[k]).trim();if(!c.name)return res.status(400).json({ok:false,error:'Customer name is required'});c.updatedAt=new Date().toISOString();saveData();res.json({ok:true,item:c});});
app.post('/api/admin/customers/:id/link',async(req,res)=>{if(!adminAuth(req,res))return;try{const id=String(req.params.id),c=customerRecord(id);if(!c)throw Error('Create or select the customer first');const st=stocks.find(x=>x.id===String(req.body?.stockId||''));if(!st||st.lifecycleStatus==='Archived'||st.status==='Archived'||String(st.originalExpiry||'')<dhakaToday())throw Error('Active, unexpired stock is required');const expiry=String(req.body?.customerExpiry||'');if(!validIsoDate(expiry)||expiry<dhakaToday())throw Error('A valid current or future Customer Expiry date is required');let profile=st.profiles?.find(x=>x.id===String(req.body?.profileId||''));if(req.body?.profileId==='NEW'){st.profiles||=[];if(st.profiles.filter(x=>x.active!==false).length>=domain.slotLimit(st.product))throw Error('Profile capacity reached');profile={id:`${st.id}-P${String(st.profiles.length+1).padStart(2,'0')}`,profile:String(req.body?.profileName||`Profile ${st.profiles.length+1}`),active:true,telegramMessages:[]};st.profiles.push(profile);}if(!profile||profile.active===false||profile.customerLinked||profile.customerId&&String(profile.customerExpiry||'')>=dhakaToday())throw Error('Choose an available profile');const old={stockId:st.id,profileId:profile.id,customerExpiry:expiry,linkedAt:new Date().toISOString()};profile.history||=[];if(profile.customerId)profile.history.push({customerId:profile.customerId,customerName:profile.customerName,customerExpiry:profile.customerExpiry,endedAt:new Date().toISOString()});Object.assign(profile,{customerId:id,customerName:c.name,resellerId:null,customerExpiry:expiry,extraDaysRequired:domain.extraDays(expiry,st.originalExpiry),customerExpiryReminderSent:{},status:'Running',linkedAt:old.linkedAt,subscriptionHistory:[...(profile.subscriptionHistory||[]),{type:'LINK',...old}]});c.subscriptionHistory||=[];c.subscriptionHistory.push({type:'LINK',...old,product:st.product,profile:profile.profile});await saveData();await syncStockTelegramMessages(st);res.status(201).json({ok:true,item:{stockId:st.id,profileId:profile.id,customerExpiry:expiry},createsSale:false});}catch(e){res.status(400).json({ok:false,error:e.message});}});
app.post('/api/admin/customers/:id/subscriptions/:stockId/:profileId/renew',async(req,res)=>{if(!adminAuth(req,res))return;try{const id=String(req.params.id),c=customerRecord(id),st=stocks.find(x=>x.id===req.params.stockId),p=st?.profiles?.find(x=>x.id===req.params.profileId);if(!c||!p||String(p.customerId)!==id)throw Error('Customer subscription not found');const before=String(p.customerExpiry||''),renewed=subscriptions.renewalExpiry({currentExpiry:before,mode:req.body?.mode,days:req.body?.days,expiryDate:req.body?.expiryDate,today:dhakaToday()}),next=renewed.expiry;const now=new Date().toISOString(),entry={type:'RENEWAL',from:before,to:next,daysAdded:renewed.daysAdded,at:now,by:String(webUser(req).id)};p.customerExpiry=next;p.extraDaysRequired=domain.extraDays(next,st.originalExpiry);p.customerExpiryReminderSent={};p.subscriptionHistory||=[];p.subscriptionHistory.push(entry);c.subscriptionHistory||=[];c.subscriptionHistory.push({...entry,stockId:st.id,profileId:p.id,product:st.product});p.updatedAt=now;await saveData();await syncStockTelegramMessages(st);let notificationSent=false,notificationError=null;try{await bot.telegram.sendMessage(Number(id),`<b>EH GAMESHOP · SUBSCRIPTION RENEWED</b>\n\nProduct: <b>${esc(st.product)}</b>\nProfile: <b>${esc(p.profile||'Your profile')}</b>\nPrevious Expiry: ${esc(fmtDate(before))}\nNew Expiry: <b>${esc(fmtDate(next))}</b>\n\nThank you for renewing with EH Gameshop.`,{parse_mode:'HTML'});notificationSent=true;p.lastCustomerRenewalNoticeAt=new Date().toISOString();await saveData();}catch(e){notificationError=e.message;}res.json({ok:true,customerExpiry:next,extraDaysRequired:p.extraDaysRequired,history:entry,notificationSent,notificationError});}catch(e){res.status(400).json({ok:false,error:e.message});}});
app.post('/api/admin/customers/:id/subscriptions/:stockId/:profileId/unlink',async(req,res)=>{if(!adminAuth(req,res))return;try{const id=String(req.params.id),c=customerRecord(id),st=stocks.find(x=>x.id===req.params.stockId),p=st?.profiles?.find(x=>x.id===req.params.profileId);if(!c||!p||String(p.customerId)!==id)throw Error('Customer subscription not found');const now=new Date().toISOString(),entry={type:'UNLINK',stockId:st.id,profileId:p.id,product:st.product,profile:p.profile,customerExpiry:p.customerExpiry,at:now,reason:String(req.body?.reason||'Admin unlinked')};p.history||=[];p.history.push({customerId:id,customerName:c.name,customerExpiry:p.customerExpiry,endedAt:now,reason:entry.reason});p.subscriptionHistory||=[];p.subscriptionHistory.push(entry);c.subscriptionHistory||=[];c.subscriptionHistory.push(entry);Object.assign(p,{customerId:null,customerName:'',customerExpiry:null,extraDaysRequired:0,resellerId:null,assignedOrderItemId:null,status:'Available',unlinkedAt:now});await saveData();await syncStockTelegramMessages(st);res.json({ok:true,history:entry});}catch(e){res.status(409).json({ok:false,error:e.message});}});
app.post('/api/admin/customers/:id/notify',(req,res)=>{if(!adminAuth(req,res))return;const id=String(req.params.id),c=customerRecord(id);if(!c)return res.status(404).json({ok:false,error:'Customer not found'});const message=String(req.body?.message||'').trim();if(!message||message.length>3500)return res.status(400).json({ok:false,error:'Message is required (maximum 3500 characters)'});bot.telegram.sendMessage(Number(id),`<b>EH GAMESHOP · SUBSCRIPTION UPDATE</b>\n\n${esc(message)}`,{parse_mode:'HTML'}).then(()=>res.json({ok:true,sent:true})).catch(e=>res.status(502).json({ok:false,error:`Notification failed: ${e.message}`}));});
app.get('/api/admin/expiry-maintenance',(req,res)=>{if(!adminAuth(req,res))return;const today=dhakaToday(),items=[];for(const st of stocks)for(const p of st.profiles||[])if(st.lifecycleStatus!=='Archived'&&st.status!=='Archived'&&p.active!==false&&p.status!=='Replaced'&&(p.customerId||p.customerLinked)&&p.customerExpiry){const bucket=expiryMaintenance.expiryBucket(p.customerExpiry,today),daysLeft=expiryMaintenance.daysUntilExpiry(p.customerExpiry,today);items.push({stockId:st.id,product:st.product,profileId:p.id,profile:p.profile,customerId:String(p.customerId),customerName:p.customerName||data.customers?.[String(p.customerId)]?.name||String(p.customerId),customerExpiry:p.customerExpiry,daysLeft,bucket,renewalHistory:(p.subscriptionHistory||[]).filter(h=>h.type==='RENEWAL').slice(-5).reverse()});}items.sort((a,b)=>a.daysLeft-b.daysLeft);res.json({ok:true,today,adminStockReminderDays:[1,0],items,summary:{expired:items.filter(x=>x.bucket==='expired').length,today:items.filter(x=>x.bucket==='today').length,within3Days:items.filter(x=>x.daysLeft>=1&&x.daysLeft<=3).length,within7Days:items.filter(x=>x.daysLeft>=4&&x.daysLeft<=7).length,active:items.filter(x=>x.daysLeft>7).length}});});


app.post('/api/admin/stocks/:id/profiles',async(req,res)=>{if(!adminAuth(req,res))return;try{const st=stocks.find(s=>s.id===req.params.id);if(!st)return res.status(404).json({ok:false,error:'Stock not found'});const customerExpiry=reminderDate(req.body?.customerExpiry);if(!customerExpiry||customerExpiry<dhakaToday())throw Error('Customer Expiry Date must be today or a future date');const linked=domain.linkNamedCustomer(st,{mode:req.body?.mode,profileId:req.body?.profileId,profile:req.body?.profile,pin:req.body?.pin,customerName:req.body?.customerName,customerExpiry});await saveData();await syncStockTelegramMessages(st);res.status(201).json({ok:true,item:linked,extraDaysRequired:linked.extraDaysRequired,createsSale:false});}catch(e){res.status(409).json({ok:false,error:e.message});}});
app.post('/api/admin/stocks/:id/profile-slots',async(req,res)=>{if(!adminAuth(req,res))return;try{const st=stocks.find(x=>x.id===req.params.id);if(!st)return res.status(404).json({ok:false,error:'Stock account not found'});if(st.lifecycleStatus==='Archived'||st.status==='Archived'||String(st.originalExpiry||'')<dhakaToday())throw Error('Expired or archived account cannot accept profiles');st.profiles||=[];const active=st.profiles.filter(p=>p.active!==false);const limit=domain.slotLimit(st.product);if(active.length>=limit)throw Error(`Profile capacity reached (${limit})`);const profile=String(req.body?.profile||'').trim(),pin=String(req.body?.pin||'').trim();if(!profile||profile.length>60)throw Error('Profile name is required (max 60 characters)');if(pin.length>30)throw Error('PIN must be 30 characters or less');if(active.some(p=>String(p.profile).toLowerCase()===profile.toLowerCase()))throw Error('Profile name already exists in this account');const n=st.profiles.length+1;const item={id:`${st.id}-P${String(n).padStart(2,'0')}`,profile,pin,active:true,status:'Available',createdAt:new Date().toISOString(),telegramMessages:[]};st.profiles.push(item);st.updatedAt=new Date().toISOString();await saveData();res.status(201).json({ok:true,item,capacity:{used:active.length+1,limit}});}catch(e){res.status(400).json({ok:false,error:e.message});}});
app.patch('/api/admin/stocks/:id/profile-slots/:profileId',async(req,res)=>{if(!adminAuth(req,res))return;try{const st=stocks.find(x=>x.id===req.params.id),p=st?.profiles?.find(x=>x.id===req.params.profileId&&x.active!==false);if(!st||!p)return res.status(404).json({ok:false,error:'Profile not found'});const name=String(req.body?.profile??p.profile).trim(),pin=String(req.body?.pin??p.pin??'').trim();if(!name||name.length>60||pin.length>30)throw Error('Enter a valid profile name and PIN');if((st.profiles||[]).some(x=>x!==p&&x.active!==false&&String(x.profile).toLowerCase()===name.toLowerCase()))throw Error('Profile name already exists');p.profile=name;p.pin=pin;if(req.body?.customerExpiry!==undefined){const expiry=String(req.body.customerExpiry||'').trim();if(expiry&&!validIsoDate(expiry))throw Error('Enter a valid Customer Expiry date');if(expiry&&!(p.customerId||p.resellerId||p.customerLinked))throw Error('Only an assigned profile can have a Customer Expiry date');p.customerExpiry=expiry||null;p.extraDaysRequired=expiry?domain.extraDays(expiry,st.originalExpiry):0;p.customerExpiryReminderSent={};}p.updatedAt=new Date().toISOString();await saveData();await syncStockTelegramMessages(st);res.json({ok:true,item:p});}catch(e){res.status(400).json({ok:false,error:e.message});}});
app.delete('/api/admin/stocks/:id/profile-slots/:profileId',(req,res)=>{if(!adminAuth(req,res))return;try{const st=stocks.find(x=>x.id===req.params.id),p=st?.profiles?.find(x=>x.id===req.params.profileId&&x.active!==false);if(!st||!p)return res.status(404).json({ok:false,error:'Profile not found'});if(p.customerId||p.customerLinked||p.assignedOrderItemId||p.reservedForItemId)throw Error('Assigned profile cannot be deleted. Unlink or release it first.');const used=(data.orders||[]).some(o=>(o.items||[]).some(i=>i.stockId===st.id&&i.stockProfileId===p.id));if(used)throw Error('This profile has order history. Keep it for audit and use Release instead.');p.active=false;p.status='Deleted';p.deletedAt=new Date().toISOString();saveData();res.json({ok:true,deleted:true});}catch(e){res.status(409).json({ok:false,error:e.message});}});
app.delete('/api/admin/stocks/:id',(req,res)=>{if(!adminAuth(req,res))return;try{const index=stocks.findIndex(x=>x.id===req.params.id);if(index<0)return res.status(404).json({ok:false,error:'Stock account not found'});const st=stocks[index];const required=`DELETE ${st.id}`;if(String(req.body?.confirm||'')!==required)return res.status(400).json({ok:false,error:`Explicit confirmation required: ${required}`});const refs=(data.orders||[]).reduce((n,o)=>n+(o.items||[]).filter(i=>i.stockId===st.id).length,0);const linked=(st.profiles||[]).filter(p=>p.customerId||p.customerLinked||p.assignedOrderItemId||p.reservedForItemId).length;if((linked||refs)&&req.body?.acknowledgeLinked!==true)return res.status(409).json({ok:false,error:`⚠️ This account has ${linked} linked profile(s) and ${refs} order item reference(s). Review the warning and confirm again to permanently delete it.`});const now=new Date().toISOString();for(const p of st.profiles||[]){const customerId=String(p.customerId||'');if(customerId){data.customers||={};const customer=data.customers[customerId];if(customer){customer.subscriptionHistory||=[];customer.subscriptionHistory.push({type:'STOCK_ACCOUNT_PERMANENTLY_DELETED',stockId:st.id,product:st.product,profileId:p.id,profile:p.profile||'',customerExpiry:p.customerExpiry||null,at:now,note:'Stock account removed by Admin after explicit warning confirmation.'});}}}data.stockDeletionAudit||=[];data.stockDeletionAudit.push({stockId:st.id,product:st.product,deletedAt:now,linkedProfiles:linked,orderItemReferences:refs,lifecycleStatus:st.lifecycleStatus||st.status||'Unknown'});stocks.splice(index,1);saveData();res.json({ok:true,deleted:true,stockId:st.id,retainedOrderReferences:refs,linkedProfilesDetached:linked,auditRecorded:true});}catch(e){res.status(409).json({ok:false,error:e.message});}});
