app.post('/api/admin/stocks/:id/profiles/:profileId/replace',async(req,res)=>{if(!adminAuth(req,res))return;try{const oldStock=stocks.find(s=>s.id===req.params.id);const oldProfile=oldStock?.profiles?.find(p=>p.id===req.params.profileId);const newStock=stocks.find(s=>s.id===String(req.body?.newStockId||''));let newProfile=newStock?.profiles?.find(p=>p.id===String(req.body?.newProfileId||''));if(!oldStock||!oldProfile||!newStock)throw Error('Old or replacement stock not found');if(String(req.body?.newProfileId||'')==='NEW'){newStock.profiles||=[];const activeSlots=newStock.profiles.filter(p=>p.active!==false);if(activeSlots.length>=domain.slotLimit(newStock.product))throw Error('Replacement account has no free profile slots');const n=newStock.profiles.length+1;newProfile={id:`${newStock.id}-P${String(n).padStart(2,'0')}`,profile:`Profile ${n}`,active:true,telegramMessages:[]};newStock.profiles.push(newProfile);}if(!newProfile||newProfile.active===false)throw Error('Replacement profile not found');if(!oldProfile.customerId||!oldProfile.customerExpiry||String(oldProfile.customerExpiry)<dhakaToday())throw Error('Only a currently running customer subscription can be replaced');if(newStock.lifecycleStatus==='Archived'||newStock.status==='Archived'||String(newStock.originalExpiry||'')<dhakaToday())throw Error('Replacement account is expired or archived');if(newProfile.customerId&&(!newProfile.customerExpiry||String(newProfile.customerExpiry)>=dhakaToday()))throw Error('Replacement profile is already assigned');if(oldStock.id===newStock.id&&oldProfile.id===newProfile.id)throw Error('Choose a different replacement profile');const customer=subscriptions.replacementSubscription(oldProfile,newStock);newProfile.history||=[];if(newProfile.customerId)newProfile.history.push({customerId:newProfile.customerId,customerName:newProfile.customerName,customerExpiry:newProfile.customerExpiry,endedAt:new Date().toISOString()});const replacementAt=new Date().toISOString(),replacementEvent={type:'REPLACEMENT',from:{stockId:oldStock.id,profileId:oldProfile.id},to:{stockId:newStock.id,profileId:newProfile.id},customerExpiry:customer.customerExpiry,at:replacementAt};newProfile.subscriptionHistory||=[];newProfile.subscriptionHistory.push(replacementEvent);oldProfile.subscriptionHistory||=[];oldProfile.subscriptionHistory.push(replacementEvent);data.customers||={};if(data.customers[customer.customerId]){data.customers[customer.customerId].subscriptionHistory||=[];data.customers[customer.customerId].subscriptionHistory.push(replacementEvent);}Object.assign(newProfile,customer,{status:'Running',replacedFrom:{stockId:oldStock.id,profileId:oldProfile.id},updatedAt:replacementAt});oldProfile.status='Replaced';oldProfile.replacedAt=new Date().toISOString();oldProfile.replacedBy={stockId:newStock.id,profileId:newProfile.id};oldProfile.history||=[];oldProfile.history.push({event:'Replacement',to:oldProfile.replacedBy,customerExpiry:oldProfile.customerExpiry,at:oldProfile.replacedAt});for(const order of data.orders||[])for(const item of order.items||[])if(item.stockId===oldStock.id&&item.stockProfileId===oldProfile.id&&String(item.customerId||order.customerId||'')===String(customer.customerId)){item.replacement={stockId:newStock.id,profileId:newProfile.id,at:oldProfile.replacedAt};item.replacementExpiry=customer.customerExpiry;}await saveData();await syncStockTelegramMessages(oldStock);if(newStock!==oldStock)await syncStockTelegramMessages(newStock);let notified=false;try{const copyText=`${newStock.product}\nEmail: ${newStock.email}\nPassword: ${newStock.password}\nProfile: ${newProfile.profile}\nExpiry: ${customer.customerExpiry}`;const rendered=renderPreview('customer_delivery',{product:newStock.product,package:'Replacement',orderId:'REPLACEMENT',itemId:newProfile.id,email:newStock.email,password:newStock.password,profile:newProfile.profile,pin:newProfile.pin||'N/A',customerExpiry:customer.customerExpiry,callbackPrefix:'delivery',copyText,orderStatus:'ACCOUNT REPLACED',paymentStatus:'NOT APPLICABLE',timelineHtml:`<pre>● ACCOUNT REPLACED · ${timelineTime(replacementAt)}</pre>`});const sent=await sendPreviewMessage(customer.customerId,rendered);domain.trackTelegramMessage(newProfile,{chatId:sent.chat.id,messageId:sent.message_id,kind:'replacement'});saveData();notified=true;}catch(sendError){console.error('Replacement notification failed:',sendError.message);}res.json({ok:true,notified,customer,oldProfile:{id:oldProfile.id,status:oldProfile.status},replacement:{stockId:newStock.id,profileId:newProfile.id,extraDaysRequired:customer.extraDaysRequired}});}catch(e){res.status(409).json({ok:false,error:e.message});}});

