async function syncStockTelegramMessages(stock){
 const related=(data.orders||[]).filter(order=>(order.items||[]).some(item=>String(item.stockId||'')===String(stock.id)));
 const summary={total:0,edited:0,replaced:0,failed:0,skipped:0};
 for(const order of related){const out=await syncOrderTelegramMessages(order);for(const key of Object.keys(summary))summary[key]+=Number(out[key]||0);}
 const notices=await syncTrackedMessages({targets:[stock],telegram:bot.telegram,save:saveData,
  render:async(_owner,ref)=>({rich:true,rich_message:{html:ref.kind==='stock_account'?stockAccountRichHtml(stock):accountUpdateNoticeHtml(stock,(stock.profiles||[]).find(p=>String(p.id)===String(ref.profileId)),ref.recipientId)}}),
  sendFallback:async(ref,rendered)=>bot.telegram.callApi('sendRichMessage',{chat_id:Number(ref.chatId),rich_message:rendered.rich_message})
 });
 for(const key of Object.keys(summary))summary[key]+=Number(notices[key]||0);
 return summary;
}

