 const allSelected=eligible>0&&selectedEligible===eligible;
 const rows=items.map((it,i)=>{const eligibleItem=youtubeItemEligibleForBulk(it),chosen=selected.has(it.id),status=String(it.status||'Pending Review');const mark=eligibleItem?`<tg-button type="callback_data" ${chosen?'style="success" ':''}data="ytadm:sel:${esc(parent.id)}:${esc(it.id)}">${chosen?'✓':'☐'}</tg-button>`:esc(status==='Cancelled'?'CANCELLED':status==='Completed'?'DONE':status.toUpperCase());return `<tr><td>${String(i+1).padStart(2,'0')}. <tg-button type="callback_data" style="link" data="ytadm:item:${esc(parent.id)}:${esc(it.id)}">${esc(it.email)}</tg-button></td><td align="center">${mark}</td></tr>`;}).join('');
 return `<h2>▶️ ADMIN · YOUTUBE REQUEST</h2><table bordered compact><tr><th>REQUEST</th><td><code>${esc(parent.id)}</code></td></tr><tr><th>RESELLER</th><td>${esc(parent.customerName||parent.resellerId||parent.customerId)}</td></tr><tr><th>TYPE</th><td>${parent.type==='family'?'FAMILY INVITE':'INDIVIDUAL'}</td></tr><tr><th>OVERALL STATUS</th><td>${esc(parent.status||'Pending Review')}</td></tr><tr><th>ITEM STATUS SUMMARY</th><td>${esc(youtubeStatusSummary(parent))}</td></tr><tr><th>SELECTED</th><td>${selectedEligible} / ${eligible} eligible</td></tr></table><p>Only unfinished email items can be selected. Completed and Cancelled items are excluded from bulk completion.</p><table bordered compact>${rows}</table><p>Tap ☐ to select an email. Tap an email address to update just that one.</p><tg-button-row><tg-button type="callback_data" data="ytadm:bulk:all:${esc(parent.id)}">${allSelected?'DESELECT ALL':'SELECT ALL'} (${eligible})</tg-button><tg-button type="callback_data" style="success" data="ytadm:bulk:ask:${esc(parent.id)}:s">COMPLETE SELECTED (${selectedEligible})</tg-button></tg-button-row><tg-button-row><tg-button type="callback_data" style="success" data="ytadm:bulk:ask:${esc(parent.id)}:a">COMPLETE ALL (${eligible})</tg-button><tg-button type="callback_data" data="ytadm:bulk:clear:${esc(parent.id)}" style="link">CLEAR</tg-button></tg-button-row><tg-button-row><tg-button type="callback_data" data="ytadm:list" style="link">← ALL REQUESTS</tg-button></tg-button-row>`;
