bot.action(/^ytadm:rask:(s|a)$/,async ctx=>{await ctx.answerCbQuery();if(!await requireAdmin(ctx))return;const mode=ctx.match[1],targets=youtubeBulkTargets(ctx.from.id,mode),itemCount=targets.reduce((n,x)=>n+(x.items||[]).filter(youtubeItemEligibleForBulk).length,0);if(!targets.length)return showYoutubeAdminList(ctx);const html=`<h2>⚠️ CONFIRM BULK COMPLETION</h2><table bordered compact><tr><th>REQUESTS</th><td><b>${targets.length}</b></td></tr><tr><th>EMAIL ITEMS</th><td><b>${itemCount}</b></td></tr></table><p>${mode==='a'?'Every unfinished email item in all listed requests':'Every unfinished email item in the selected requests only'} will be marked COMPLETED. Completed and Cancelled items are not changed. Requests that are not included stay exactly as they are.</p><p>This records that EH Gameshop has sent the invitation / finished its processing. It does not mean the recipient has accepted Google's invitation.</p><tg-button-row><tg-button type="callback_data" style="success" data="ytadm:rdo:${mode}">CONFIRM · COMPLETE ${itemCount}</tg-button><tg-button type="callback_data" data="ytadm:list" style="link">CANCEL</tg-button></tg-button-row>`;return ctx.telegram.callApi('editMessageText',{chat_id:ctx.chat.id,message_id:ctx.callbackQuery.message.message_id,rich_message:{html}});});
bot.action(/^ytadm:rdo:(s|a)$/,async ctx=>{await ctx.answerCbQuery();if(!await requireAdmin(ctx))return;const mode=ctx.match[1],targets=youtubeBulkTargets(ctx.from.id,mode);if(!targets.length)return showYoutubeAdminList(ctx);let done=0;for(const parent of targets){const items=(parent.items||[]).filter(youtubeItemEligibleForBulk);for(const item of items){youtubeRequests.updateYoutubeItemStatus(item,'Completed',ctx.from.id);done++;}updateYoutubeParentStatus(parent);youtubeAdminSelection.clear(data.youtubeAdminSelections,`${ctx.from.id}:${parent.id}`);}youtubeAdminSelection.clear(data.youtubeAdminSelections,youtubeAdminSelection.requestKey(ctx.from.id));await saveData();let notifyFailed=0;for(const parent of targets){try{await notifyYoutubeRequestOwner(parent);}catch(e){notifyFailed++;console.error('YouTube bulk notification failed:',parent.id,e.message);}}const html=`<h2>✅ BULK UPDATE COMPLETE</h2><table bordered compact><tr><th>REQUESTS UPDATED</th><td><b>${targets.length}</b></td></tr><tr><th>EMAIL ITEMS COMPLETED</th><td><b>${done}</b></td></tr></table>${notifyFailed?`<p>${notifyFailed} reseller notification(s) could not be delivered; the data was saved.</p>`:''}<tg-button-row><tg-button type="callback_data" data="ytadm:list" style="primary">← ALL REQUESTS</tg-button></tg-button-row>`;return ctx.telegram.callApi('editMessageText',{chat_id:ctx.chat.id,message_id:ctx.callbackQuery.message.message_id,rich_message:{html}});});
bot.action(/^ytadm:item:(YT-[A-Za-z0-9-]+):(YTI-[A-Za-z0-9-]+)$/,async ctx=>{await ctx.answerCbQuery();if(!await requireAdmin(ctx))return;const parent=(data.youtubeRequests||[]).find(x=>x.id===ctx.match[1]),item=parent?.items?.find(x=>x.id===ctx.match[2]);if(!parent||!item)return ctx.reply('YouTube email item not found.');const buttons=[['Accepted','accepted'],['Processing','processing'],['Hold','hold'],['Completed','done'],['Cancelled','cancelled']].map(([label,key])=>`<tg-button type="callback_data" ${key==='hold'?'':`style="${key==='done'?'success':key==='cancelled'?'danger':'primary'}" `}data="ya:s:${esc(parent.id)}:${esc(item.id)}:${({accepted:"a",processing:"p",hold:"h",done:"d",cancelled:"r"})[key]}">${key==='hold'?'🟠 ':''}${label.toUpperCase()}</tg-button>`);const html=`<h2>▶️ UPDATE YOUTUBE EMAIL</h2><table bordered compact><tr><th>REQUEST</th><td><code>${esc(parent.id)}</code></td></tr><tr><th>EMAIL</th><td><code>${esc(item.email)}</code></td></tr><tr><th>CURRENT STATUS</th><td><b>${esc(item.status||'Pending Review')}</b></td></tr></table><p>Select the current processing status. Mark COMPLETED after sending the Google Family invitation manually.</p><tg-button-row>${buttons[0]}${buttons[1]}</tg-button-row><tg-button-row>${buttons[2]}${buttons[3]}</tg-button-row><tg-button-row>${buttons[4]}</tg-button-row><tg-button-row><tg-button type="callback_data" data="ytadm:req:${esc(parent.id)}" style="link">← REQUEST</tg-button></tg-button-row>`;return ctx.telegram.callApi('editMessageText',{chat_id:ctx.chat.id,message_id:ctx.callbackQuery.message.message_id,rich_message:{html}});});
bot.action(/^ya:s:(YT-[A-Za-z0-9-]+):(YTI-[A-Za-z0-9-]+):(a|p|i|h|d|r)$/,async ctx=>{await ctx.answerCbQuery();if(!await requireAdmin(ctx))return;const parent=(data.youtubeRequests||[]).find(x=>x.id===ctx.match[1]),item=parent?.items?.find(x=>x.id===ctx.match[2]);if(!parent||!item)return ctx.reply('YouTube email item not found.');const statusMap={a:'Accepted',p:'Processing',i:'Completed',h:'Hold',d:'Completed',r:'Cancelled'};/* i = legacy Invited button on old messages; treated as Completed */try{youtubeRequests.updateYoutubeItemStatus(item,statusMap[ctx.match[3]],ctx.from.id);updateYoutubeParentStatus(parent);await saveData();await notifyYoutubeRequestOwner(parent);}catch(e){return ctx.reply(`Could not update YouTube request: ${e.message}`);}const rows=(parent.items||[]).map((it,i)=>`<tr><td>${String(i+1).padStart(2,'0')} · <code>${esc(it.email)}</code></td><td>${esc(it.status)}</td><td><tg-button type="callback_data" style="primary" data="ytadm:item:${esc(parent.id)}:${esc(it.id)}">UPDATE</tg-button></td></tr>`).join('');const html=`<h2>✅ YOUTUBE STATUS UPDATED</h2><table bordered compact><tr><th>REQUEST</th><td><code>${esc(parent.id)}</code></td></tr><tr><th>OVERALL STATUS</th><td><b>${esc(parent.status)}</b></td></tr><tr><th>ITEM STATUS SUMMARY</th><td>${esc(youtubeStatusSummary(parent))}</td></tr></table><table bordered compact><tr><th>EMAIL</th><th>STATUS</th><th>ACTION</th></tr>${rows}</table><tg-button-row><tg-button type="callback_data" data="ytadm:list" style="link">← ALL REQUESTS</tg-button></tg-button-row>`;return ctx.telegram.callApi('editMessageText',{chat_id:ctx.chat.id,message_id:ctx.callbackQuery.message.message_id,rich_message:{html}});});
app.get("/api/me/youtube",(req,res)=>{const u=webUser(req);if(!u)return res.status(401).json({ok:false});const id=String(u.id),admin=ADMIN_IDS.has(id);const rows=(data.youtubeRequests||[]).filter(x=>admin||String(x.customerId)===id||String(x.resellerId||'')===id).map(x=>({id:x.id,type:x.type,status:x.status,createdAt:x.createdAt,items:(x.items||[]).map(it=>({id:it.id,email:it.email,status:it.status,replacementCount:Number(it.replacementCount||0),replacementAvailable:Number(it.replacementCount||0)<1,notes:admin?it.notes:undefined,history:it.history||[]}))}));res.json({ok:true,items:rows});});
app.post("/api/youtube/requests/:id/items/:itemId/replace",async(req,res)=>{const u=webUser(req);if(!u)return res.status(401).json({ok:false});const parent=(data.youtubeRequests||[]).find(v=>v.id===req.params.id);if(!parent)return res.status(404).json({ok:false,error:"Request not found"});const owner=String(parent.resellerId||parent.customerId||'');if(String(u.id)!==owner&&!ADMIN_IDS.has(String(u.id)))return res.status(403).json({ok:false,error:"Only the request owner or Admin can change this email"});const item=(parent.items||[]).find(v=>v.id===req.params.itemId);if(!item)return res.status(404).json({ok:false,error:"Email item not found"});try{youtubeRequests.replaceYoutubeItem(item,req.body?.newEmail,req.body?.reason,u.id);updateYoutubeParentStatus(parent);await saveData();await notifyYoutubeRequestOwner(parent);const adminHtml=`<h2>✉️ CUSTOMER-PROVIDED YOUTUBE EMAIL</h2><table bordered compact><tr><th>REQUEST</th><td><code>${esc(parent.id)}</code></td></tr><tr><th>TYPE</th><td>${parent.type==='family'?'FAMILY INVITE':'INDIVIDUAL'}</td></tr><tr><th>NEW EMAIL</th><td><code>${esc(item.email)}</code></td></tr><tr><th>STATUS</th><td>PENDING REVIEW</td></tr></table><p>The customer/reseller supplied this new email. EH Gameshop is not supplying a replacement account.</p><tg-button-row><tg-button type="callback_data" style="primary" data="ytadm:item:${esc(parent.id)}:${esc(item.id)}">UPDATE REQUEST</tg-button></tg-button-row>`;for(const adminId of ADMIN_IDS){try{const sent=await bot.telegram.callApi('sendRichMessage',{chat_id:Number(adminId),rich_message:{html:adminHtml}});domain.trackTelegramMessage(parent,{chatId:sent.chat.id,messageId:sent.message_id,kind:'youtube_admin_request'});}catch(e){console.error('YouTube email change Admin notification failed:',parent.id,e.message);}}await saveData();return res.json({ok:true,item:{id:item.id,email:item.email,replacementCount:1,status:item.status}});}catch(e){return res.status(e.message.includes("already been used")?409:400).json({ok:false,error:e.message});}});
