app.post("/api/admin/test-orders",async(req,res)=>{const u=webUser(req);if(!u)return res.status(401).json({ok:false});if(!ADMIN_IDS.has(String(u.id)))return res.status(403).json({ok:false});try{const resellerId=String(req.body?.resellerId||'');const reseller=data.resellers?.[resellerId];if(!reseller?.active)throw Error('Choose an active reseller');const productKey=String(req.body?.productId||req.body?.product||'').trim();const productRow=resellerProductCatalog().find(p=>p.active!==false&&(String(p.id||p.name).toLowerCase()===productKey.toLowerCase()||String(p.name).toLowerCase()===productKey.toLowerCase()));const product=String(productRow?.name||req.body?.product||'').trim();if(!product)throw Error('Choose a product');const quantity=Number(req.body?.quantity||1);const priceEach=Number(req.body?.priceEach??productRow?.price);const customerId=String(req.body?.customerId||resellerId);if(!/^[0-9]{5,20}$/.test(customerId))throw Error("Enter a valid numeric Telegram ID for the test recipient");if(!Number.isFinite(priceEach)||priceEach<=0)throw Error('Set a valid test price');const order=domain.createResellerBuyOrder(data,{resellerId,customerId,customerName:String(req.body?.customerName||'Admin Test Customer'),product,quantity,priceEach});order.isTest=true;order.testCreatedBy=String(u.id);order.deliveryMode=req.body?.deliveryMode==='Manual'?'Manual':'Auto';order.testMode=true;order.status=order.deliveryMode==='Manual'?'Manual Delivery':'Awaiting Stock';for(const item of order.items){item.isTest=true;item.product=product;item.packageName=String(productRow?.package||req.body?.packageName||'Standard');item.durationDays=Number(productRow?.durationDays||req.body?.durationDays||30);item.status=order.status;}for(const row of data.ledger||[])if(row.orderId===order.id)row.isTest=true;recordOrderEvent(order,'TEST_ORDER_CREATED',u.id,{deliveryMode:order.deliveryMode,quantity,product});await saveData();let delivery=[];if(order.deliveryMode==='Auto')delivery=await deliverResellerAutoOrder(order);return res.status(201).json({ok:true,order:{id:order.id,price:order.price,status:order.status,isTest:true,deliveryMode:order.deliveryMode,items:order.items},delivery});}catch(e){return res.status(400).json({ok:false,error:e.message});}});
app.delete("/api/admin/test-orders/:id",async(req,res)=>{const u=webUser(req);if(!u)return res.status(401).json({ok:false});if(!ADMIN_IDS.has(String(u.id)))return res.status(403).json({ok:false});const order=(data.orders||[]).find(x=>x.id===req.params.id&&x.isTest===true);if(!order)return res.status(404).json({ok:false,error:'Test order not found'});for(const item of order.items||[])for(const ref of item.telegramMessages||[]){try{await bot.telegram.deleteMessage(Number(ref.chatId),Number(ref.messageId));}catch{}}const result=domain.deleteTestOrder(data,order.id);await saveData();return res.json({ok:true,deleted:order.id,...result});});
bot.action(/^delivery_more:([A-Za-z0-9-]+):([A-Za-z0-9-]+)$/,(async ctx=>{const o=(data.orders||[]).find(x=>x.id===ctx.match[1]);const item=o?.items?.find(x=>x.id===ctx.match[2]);if(!o||!item)return ctx.answerCbQuery("Order details are unavailable.",{show_alert:true});const recipient=String(item.customerId||o.customerId||o.resellerId||"");if(String(ctx.from.id)!==recipient&&!isAdmin(ctx))return ctx.answerCbQuery("This delivery belongs to another account.",{show_alert:true});await ctx.answerCbQuery();return ctx.reply(`📦 <b>ADDITIONAL ORDER DETAILS</b>\nOrder: <code>${esc(o.id)}</code>\nItem: <code>${esc(item.id)}</code>\nProduct: ${esc(item.product||o.product)}\nQuantity: ${Number(item.quantity||1)}\nOrder Time: ${esc(dhakaTime(o.createdAt))}\nDelivery Time: ${esc(item.deliveredAt?dhakaTime(item.deliveredAt):"Pending")}`,{parse_mode:"HTML"});}));
bot.action(/^delivery_live:([A-Za-z0-9-]+):([A-Za-z0-9-]+)$/,(async ctx=>{const o=(data.orders||[]).find(x=>x.id===ctx.match[1]);const item=o?.items?.find(x=>x.id===ctx.match[2]);if(!o||!item)return ctx.answerCbQuery("Order not found.",{show_alert:true});const recipient=String(item.customerId||o.customerId||o.resellerId||"");if(String(ctx.from.id)!==recipient&&!isAdmin(ctx))return ctx.answerCbQuery("This order belongs to another account.",{show_alert:true});return ctx.answerCbQuery(`LIVE UPDATE · ${item.status||o.status} · ${item.deliveredAt?dhakaTime(item.deliveredAt):"In progress"}`,{show_alert:true});}));
app.get('/api/admin/reseller-settings',(req,res)=>{if(!adminAuth(req,res))return;res.json({ok:true,resellers:Object.values(data.resellers||{}).map(r=>({id:r.id,name:r.name,active:r.active,creditAuthorized:Boolean(r.creditAuthorized),tier:r.tier||'Rate 1',specialPrices:r.specialPrices||{},tierPrices:r.tierPrices||{}})),products:resellerProductCatalog().map(p=>({id:p.id,name:p.name,price:Number(p.price||stockPrices[p.name]||0),active:p.active!==false}))});});
app.patch('/api/admin/resellers/:id/credit',(req,res)=>{if(!adminAuth(req,res))return;const r=data.resellers?.[req.params.id];if(!r)return res.status(404).json({ok:false,error:'Reseller not found'});r.creditAuthorized=req.body?.authorized===true;r.creditAuthorizedAt=new Date().toISOString();r.creditAuthorizedBy=String(webUser(req).id);saveData();res.json({ok:true,reseller:{id:r.id,creditAuthorized:r.creditAuthorized}});});
app.put('/api/admin/resellers/:id/pricing',(req,res)=>{if(!adminAuth(req,res))return;const r=data.resellers?.[req.params.id];if(!r)return res.status(404).json({ok:false,error:'Reseller not found'});const tier=String(req.body?.tier||r.tier||'Rate 1');if(!['Rate 1','Rate 2','Rate 3'].includes(tier))return res.status(400).json({ok:false,error:'Invalid rate tier'});const specials=req.body?.specialPrices||{},tierPrices=req.body?.tierPrices||{};for(const [k,v] of Object.entries(specials))if(!Number.isFinite(Number(v))||Number(v)<=0)return res.status(400).json({ok:false,error:`Invalid special price for ${k}`});for(const [t,prices] of Object.entries(tierPrices)){if(!['Rate 1','Rate 2','Rate 3'].includes(t)||!prices||typeof prices!=='object'||Array.isArray(prices))return res.status(400).json({ok:false,error:'Invalid tier price matrix'});for(const [k,v] of Object.entries(prices))if(!Number.isFinite(Number(v))||Number(v)<=0)return res.status(400).json({ok:false,error:`Invalid ${t} price for ${k}`});}r.tier=tier;r.specialPrices={...specials};r.tierPrices=Object.fromEntries(['Rate 1','Rate 2','Rate 3'].map(t=>[t,{...(tierPrices[t]||{})}]));saveData();res.json({ok:true,reseller:{id:r.id,tier:r.tier,specialPrices:r.specialPrices,tierPrices:r.tierPrices}});});
app.get('/api/admin/reseller-customers',(req,res)=>{if(!adminAuth(req,res))return;const q=String(req.query.q||'').trim().toLowerCase();const orders=(data.orders||[]).filter(o=>o.resellerId&&!o.isTest&&(!q||[o.resellerId,o.customerId,o.customerName,o.id,...(o.items||[]).flatMap(i=>[i.id,i.product,i.accountEmail])].some(v=>String(v||'').toLowerCase().includes(q))));const ids=new Set();for(const o of orders){if(o.customerId)ids.add(String(o.customerId));for(const i of o.items||[])if(i.customerId)ids.add(String(i.customerId));}const profiles=[];for(const st of stocks)for(const p of st.profiles||[])if(ids.has(String(p.customerId))||q&&[p.customerName,p.customerId,p.profile].some(v=>String(v||'').toLowerCase().includes(q)))profiles.push({stockId:st.id,product:st.product,profile:p.profile,customerId:p.customerId,customerName:p.customerName,customerExpiry:p.customerExpiry,history:p.history||[]});res.json({ok:true,customers:[...ids].map(id=>({id,name:data.customers?.[id]?.name||orders.find(o=>String(o.customerId)===id)?.customerName||id,orders:orders.filter(o=>String(o.customerId)===id||(o.items||[]).some(i=>String(i.customerId)===id))})),orders,profiles});});
app.post("/api/admin/reseller-settlement",(req,res)=>res.status(410).json({ok:false,error:"Direct settlement is disabled. Verify and confirm a pending due-clearance request."}));
app.get("/health",(_req,res)=>res.json({ok:true,service:"EH Gameshop"}));
const PORT=Number(process.env.PORT||3000);

bot.catch(error => console.error("Telegram bot error:", error));

async function runResellerSlaChecks(){const now=Date.now();for(const o of data.orders||[]){if(!o.resellerId||!o.deliveryDueAt||o.slaAlertSent||new Date(o.deliveryDueAt).getTime()>now)continue;const pending=(o.items||[]).filter(i=>i.status!=='Completed'&&i.status!=='Rejected');if(!pending.length)continue;for(const adminId of ADMIN_IDS){try{await bot.telegram.sendMessage(Number(adminId),`⏰ <b>RESELLER 30-MINUTE SLA BREACHED</b>\nOrder: <code>${esc(o.id)}</code>\nReseller: <code>${esc(o.resellerId)}</code>\nPending Items: ${pending.length}\nPlease review stock / delivery.`,{parse_mode:'HTML'});}catch{}}try{await bot.telegram.sendMessage(Number(o.resellerId),`⚠️ Order ${o.id} is taking longer than the 30-minute target. Admin has been alerted.`);}catch{}o.slaAlertSent=true;o.slaBreachedAt=new Date().toISOString();saveData();}}

async function runTicketHoldChecks(){const now=Date.now();for(const t of data.tickets||[]){if(!["Hold","On Hold"].includes(t.status)||!t.reviewAt||t.holdReminderSent||new Date(t.reviewAt).getTime()>now)continue;for(const adminId of ADMIN_IDS){try{await bot.telegram.sendMessage(Number(adminId),`⏰ <b>SUPPORT HOLD REVIEW DUE</b>\nTicket: <code>${esc(t.id)}</code>\nCustomer: <code>${esc(t.customerId)}</code>\nSubject: ${esc(t.subject||t.issue)}`,{parse_mode:"HTML"});}catch(e){console.error("Hold reminder failed",t.id,e.message);}}t.holdReminderSent=true;saveData();}}

async function startApplication() {
  await connectMongoAndLoad();
  app.listen(PORT, "0.0.0.0", () => console.log(`EH Gameshop API listening on ${PORT}`));
  bot.launch().catch(e => console.error("Telegram bot launch failed:", e.message));
  if(process.env.WEB_APP_URL){try{const miniAppUrl=new URL(process.env.WEB_APP_URL);miniAppUrl.searchParams.set("v",APP_VERSION);await bot.telegram.setChatMenuButton({menu_button:{type:"web_app",text:"Open EH Gameshop",web_app:{url:miniAppUrl.toString()}}});console.log("Telegram Mini App menu button configured:",miniAppUrl.toString());}catch(e){console.error("Mini App menu button setup failed:",e.message);}}
  for(const [resellerId,reseller] of Object.entries(data.resellers||{})){if(!reseller?.active||ADMIN_IDS.has(String(resellerId)))continue;try{await bot.telegram.setChatMenuButton({chat_id:Number(resellerId),menu_button:{type:"commands"}});}catch(e){console.error('Could not disable reseller Mini App menu button for',resellerId,e.message);}}
  console.log("EH Gameshop Bot running with MongoDB storage.");
  runExpiryChecks().catch(e => console.error("Initial expiry check:", e.message));
  runReminderAccountChecks().catch(e => console.error("Initial reminder-only account check:", e.message));
  runTicketHoldChecks().catch(e => console.error("Initial ticket reminder:", e.message));
  runResellerSlaChecks().catch(e => console.error("Initial reseller SLA check:", e.message));
  setInterval(()=>runResellerSlaChecks().catch(e=>console.error("Reseller SLA check:",e.message)),60*1000);
  setInterval(() => runExpiryChecks().catch(e => console.error("Scheduled expiry check:", e.message)), 5 * 60 * 1000);
  setInterval(() => runReminderAccountChecks().catch(e => console.error("Scheduled reminder-only account check:", e.message)), 30 * 60 * 1000);
  setInterval(() => runTicketHoldChecks().catch(e => console.error("Scheduled ticket reminder:", e.message)), 60 * 1000);
}

startApplication().catch(error => {
  console.error("Startup failed:", error.message);
  process.exit(1);
});

async function shutdown(signal) {
  console.log(`${signal} received; waiting for MongoDB writes...`);
  try { await mongoWriteChain; } catch {}
  try { bot.stop(signal); } catch {}
  try { await mongoClient?.close(); } catch {}
  process.exit(0);
}
process.once("SIGINT", () => shutdown("SIGINT"));
process.once("SIGTERM", () => shutdown("SIGTERM"));
